include { OPT_FLIP  } from 'nf-core/opt/flip'
include { OPT_TRACK } from 'nf-core/opt/track'
include { OPT_STAT  } from 'nf-core/opt/stat'


workflow OPT_FLIP_TRACK_STAT {
    take:
    ch_probe_fasta   // channel: [ val(meta), [ "panel_probes_sequences.fasta" ] ]
    ch_references    // channel: [ val(meta), ["reference_annotations.gff"], ["reference_annotations.fa"] ]
    ch_gene_synonyms // channel: [ "path-to-gene-synonyms" ]

    main:

    ch_summary = channel.empty()

    // correct probes that are aligning to opposite strand with `flip`
    OPT_FLIP(ch_probe_fasta, ch_references)

    // align query probe sequences to target transcriptome
    OPT_TRACK(OPT_FLIP.out.fwd_oriented_fa, ch_references)

    // summarizes opt binding predictions
    OPT_STAT(OPT_TRACK.out.probes2target, OPT_FLIP.out.fwd_oriented_fa, ch_gene_synonyms)

    ch_summary = OPT_STAT.out.summary

    emit:
    summary  = ch_summary  // channel: [ val(meta), ["collapsed_summary.tsv"]]
}

nextflow_workflow {

    name "Test OPT_FLIP_TRACK_STAT"
    script "../main.nf"
    workflow "OPT_FLIP_TRACK_STAT"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "opt"
    tag "opt/flip"
    tag "opt/stat"
    tag "opt/track"
    tag "subworkflows/opt_flip_track_stat"

    test("off-target probe tracker - opt") {

        when {
            workflow {
                """
                input[0] = Channel.of(
                        [
                            [ id: 'test_probes' ],
                            file(params.modules_testdata_base_path + 'spatial_omics/probe_detection/probes.fa', checkIfExists: true)
                        ]
                    )
                input[1] = [
                    [ id:'test_references' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.gtf', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/minigenome.fa', checkIfExists: true)
                ]
                input[2] = [file(params.modules_testdata_base_path + 'spatial_omics/probe_detection/gene_synonyms.csv', checkIfExists: true)]
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() },
            )
        }
    }

}
